-- Four newly verified products only. Existing products/history are never rewritten.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table batch_input as select * from jsonb_to_recordset($data$[{"shop": "NinaJiaStudio", "listing_id": "4585567382", "source_url": "https://www.etsy.com/listing/4585567382/chinese-landscape-tote-bag-black", "category": "Textile Bags", "board_id": "713820678377803445", "new_title": "Black and Ivory Landscape Jacquard Tote Bag", "body": "An ink-wash landscape of mountains and trees decorates this ivory and black jacquard tote, finished with long black handles. From NinaJiaStudio. Explore the original Etsy listing for current options.", "image_url": "https://i.etsystatic.com/61131894/r/il/dcec8c/8600747030/il_1588xN.8600747030_7jcn.jpg", "checked_at": "2026-10-13T04:12:20.721Z", "facebook_draft": "An ink-wash landscape of mountains and trees decorates this ivory and black jacquard tote, finished with long black handles. From NinaJiaStudio. Explore the original Etsy listing for current options. Browse here: https://www.etsy.com/listing/4585567382/chinese-landscape-tote-bag-black"}, {"shop": "NinaJiaStudio", "listing_id": "4585556630", "source_url": "https://www.etsy.com/listing/4585556630/red-plum-blossom-tote-bag-chinese", "category": "Textile Bags", "board_id": "713820678377803445", "new_title": "Red Blossom Jacquard Shoulder Tote", "body": "Red blossoms and branching motifs stand out against an ivory background, with red double handles completing the floral design. From NinaJiaStudio. See the original Etsy listing for current options.", "image_url": "https://i.etsystatic.com/61131894/r/il/923472/8600658454/il_1588xN.8600658454_63we.jpg", "checked_at": "2026-10-13T04:12:53.726Z", "facebook_draft": "Red blossoms and branching motifs stand out against an ivory background, with red double handles completing the floral design. From NinaJiaStudio. See the original Etsy listing for current options. Browse here: https://www.etsy.com/listing/4585556630/red-plum-blossom-tote-bag-chinese"}, {"shop": "NngGoods", "listing_id": "4538093833", "source_url": "https://www.etsy.com/listing/4538093833/natural-travertine-square-knob-raw-stone", "category": "Cabinet Knobs & Pulls", "board_id": "713820678377803412", "new_title": "Natural Travertine Square Cabinet Knobs", "body": "Bring earthy texture to cabinets and drawers with porous, square-shaped stone knobs. Natural pores, edges and colors vary between pieces. From NngGoods. Check the original Etsy listing for fitting details and options.", "image_url": "https://i.etsystatic.com/57194200/r/il/cb19c7/8483607528/il_1588xN.8483607528_kgzd.jpg", "checked_at": "2026-10-13T04:13:22.440Z", "facebook_draft": "Bring earthy texture to cabinets and drawers with porous, square-shaped stone knobs. Natural pores, edges and colors vary between pieces. From NngGoods. Check the original Etsy listing for fitting details and options. Browse here: https://www.etsy.com/listing/4538093833/natural-travertine-square-knob-raw-stone"}, {"shop": "NngGoods", "listing_id": "4537632729", "source_url": "https://www.etsy.com/listing/4537632729/white-veined-stone-cabinet-knob-natural", "category": "Cabinet Knobs & Pulls", "board_id": "713820678377803412", "new_title": "White Veined Stone Knobs with Gold-Tone Bases", "body": "Irregular white stone faces with natural veining meet gold-tone mounting bases. An organic accent for drawers and cabinets; each stone varies. From NngGoods. Visit the original Etsy listing for fitting details and options.", "image_url": "https://i.etsystatic.com/57194200/r/il/b06143/8434244566/il_1588xN.8434244566_ov5j.jpg", "checked_at": "2026-10-13T04:13:50.907Z", "facebook_draft": "Irregular white stone faces with natural veining meet gold-tone mounting bases. An organic accent for drawers and cabinets; each stone varies. From NngGoods. Visit the original Etsy listing for fitting details and options. Browse here: https://www.etsy.com/listing/4537632729/white-veined-stone-cabinet-knob-natural"}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle='ivy5205' and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)='ivy5205')<>4 then raise exception 'P5 routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','p5-20261013-2'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261013',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261013',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle='ivy5205' and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
